  'pb.v2.p.guidanceTitle': { zh: '指导材料(历史)', en: 'Guidance materials (history)', fr: 'Documents de guidage (historique)' },
  'pb.v2.p.guidanceHint': { zh: '这些是之前生成的指导材料,完整件在「材料」页签里:', en: 'Previously generated guidance; the full files are in the Materials tab:', fr: 'Guidages générés précédemment ; fichiers complets dans l’onglet Documents :' },
  'pb.v2.p.localNotice': { zh: '已用本地聚合生成(AI 网关未配置/未返回):内容来自 JD、题库往期原题与短板,接入 AI 后重新生成可得到完整稿子。', en: 'Generated with local aggregation (AI gateway not configured / no response): content comes from the JD, past questions and weaknesses. Regenerate after connecting AI for the full script.', fr: 'Généré par agrégation locale (passerelle IA non configurée / sans réponse) : contenu issu de l’offre, des questions passées et des faiblesses. Régénérez avec l’IA connectée pour le script complet.' },
