  'pb.v2.p.tgFlow': { zh: '流程稿与要点(寒暄/介绍/反问/收尾)', en: 'Flow scripts & points (warm-up / intro / your questions / wrap-up)', fr: 'Scripts et points du déroulé (accueil / présentation / vos questions / conclusion)' },
