  'pb.v2.p.docTitle': { zh: '{company} · Round {n} {stage} 备考报告', en: '{company} · Round {n} {stage} prep report', fr: '{company} · Tour {n} {stage} — rapport de préparation' },

  // ---------- 备考:数据源状态 + 默认框架(2026-10-21) ----------
  'pb.v2.p.fwNote': { zh: '默认框架(尚未生成专属报告)—— 按面试流程的通用要点先备着;生成后按 JD / 题库 / 抓取的面经定制。', en: 'Default framework (no tailored report yet) — general points along the interview flow; generate to tailor it to the JD, question bank and fetched experiences.', fr: 'Cadre par défaut (pas encore de rapport personnalisé) — points généraux selon le déroulement ; générez pour l’adapter à l’offre, à la banque de questions et aux retours récupérés.' },
  'pb.v2.p.srcQb': { zh: '题库匹配', en: 'Question bank', fr: 'Banque de questions' },
  'pb.v2.p.srcWeb': { zh: '网络面经', en: 'Web experiences', fr: 'Retours web' },
  'pb.v2.p.srcGlassdoor': { zh: 'Glassdoor 面经', en: 'Glassdoor', fr: 'Glassdoor' },
  'pb.v2.p.srcManual': { zh: '手贴面经', en: 'Pasted experiences', fr: 'Retours collés' },
