  'pb.v2.i.typeNote': { zh: '备注', en: 'Note', fr: 'Note' },
  'pb.v2.i.hintEmail': { zh: '把邮件全文粘贴进来(含发件人/日期/主题行最好),或直接粘贴邮件截图(可多张),点「解析预览」先看系统提取对不对,再确认归属。截图会经 AI 识别成文字后按主题聚合解析。', en: 'Paste the full email (ideally including the From/Date/Subject lines), or paste email screenshots (several at once), then click “Parse preview” to check the extraction before confirming where it belongs. Screenshots are recognized by AI and grouped by subject.', fr: 'Collez l’e-mail complet (avec les lignes De/Date/Objet si possible), ou collez des captures d’e-mails (plusieurs à la fois), puis cliquez « Aperçu de l’analyse » pour vérifier l’extraction. Les captures sont reconnues par l’IA et regroupées par objet.' },
  'pb.v2.i.hintTranscriptUpload': { zh: '上传一个录音文件,或直接把录音文件 Ctrl+V 粘贴进来。保存后系统会自动转写,结果出现在归属轮次的「面试实录」里。', en: 'Upload a recording file, or paste one straight in with Ctrl+V. After saving, it is transcribed automatically and the result appears in the assigned round’s “Interview record”.', fr: 'Importez un fichier audio, ou collez-le directement avec Ctrl+V. Après l’enregistrement, il est transcrit automatiquement et le résultat apparaît dans le « Compte rendu » du tour attribué.' },
